"""Every refusal `assert_guarded_write` makes *before* the call goes out (checkpoint B1-B4).

These are usage errors, so they raise `ProbeError` rather than failing an assertion: a misused
helper must never be able to read as a pass. They run first for a second reason — a gate that
fires after the call has already let a destructive tool run, and the expectation is fully known
beforehand, so there is no reason for it to run late.

The question each one asks is not "was an argument passed" but "does the argument cover the
claim". That is one defect seen four times, and every time it was an expectation that is
*present* and checks *nothing*:

* **B2** `expect_person={"I0001": {}}` is truthy, so the D16 gate opens onto an empty loop.
* **B3** a mistyped path with an expected `None` is a tautology in both halves of the check.
* **B4** a `bulk` call whose `expect_person` covers part of `arguments["items"]` leaves the rest
  unobservable — a field write moves no count, so nothing else can see it.
* **B1** a negative `expect_delta` with no `expect_removed` asserts that *something* vanished,
  which the wrong object vanishing satisfies just as well.
"""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

from .docker_util import ProbeError
from .movement import EVERYTHING, Declared
from .self_report import SelfReport

# The two shapes that write to a person and report about it — exactly the shapes a skipped PUT
# makes invisible, so both must name what the tree has to say afterwards.
NEEDS_EXPECT_PERSON = ("person", "bulk")


def reject_unusable_call(
    name: str,
    tool: str,
    arguments: Mapping[str, Any],
    self_report: SelfReport,
    expect_person: Mapping[str, Mapping[str, Any]] | None,
    expect_delta: Mapping[str, int],
    id_namespace: str | None,
) -> None:
    """The whole gate, in the order a caller meets it."""
    if self_report in NEEDS_EXPECT_PERSON and not expect_person:
        raise ProbeError(
            f"{name}: self_report={self_report!r} requires expect_person={{gramps_id: {{path: value}}}} "
            "— without that REST re-read the helper certifies a tool that never wrote (D16)"
        )
    _reject_hollow_expectations(name, expect_person)
    _reject_uncovered_batch(name, self_report, arguments, expect_person)
    if self_report == "unguarded" and any(dict(expect_delta).values()):
        raise ProbeError(
            f"{name}: self_report='unguarded' means the tool takes no count snapshot and reports no "
            f"before/after ({tool} is one of three, gramps_client.py:979-1048) — assert its effect "
            "structurally in the test instead of claiming a delta nothing corroborates"
        )
    if self_report == "id" and not id_namespace:
        raise ProbeError(f"{name}: self_report='id' requires id_namespace= to look the new id up")


def reject_uncovered_removal(
    name: str, expect_delta: Mapping[str, int], expect_removed: Declared | None
) -> None:
    """A namespace that loses objects has to name them (B1).

    There is no derivable substitute. Reading the id out of `arguments` would work for the three
    shipped delete tools and become a silent no-op for the fourth one under a different
    parameter name — which is exactly the failure B4 was raised about.
    """
    declared = dict(expect_removed or {})
    for namespace, value in sorted(dict(expect_delta).items()):
        if value >= 0 or declared.get(namespace) is EVERYTHING:
            continue
        if not declared.get(namespace):
            raise ProbeError(
                f"{name}: expect_delta says {namespace} loses {-value}, so "
                f"expect_removed={{{namespace!r}: [...]}} is required — a count that moved by "
                f"{value} is satisfied just as well by the wrong object leaving, and the tool's "
                "own report only echoes the id it was handed (checkpoint B1). Use EVERYTHING "
                "for a wipe."
            )


def _reject_hollow_expectations(
    name: str, expect_person: Mapping[str, Mapping[str, Any]] | None
) -> None:
    """An entry that names a person but no field, or a field but no falsifiable value (B2, B3)."""
    for gramps_id, fields in dict(expect_person or {}).items():
        if not fields:
            raise ProbeError(
                f"{name}: expect_person[{gramps_id!r}] names no field, so the mandatory REST "
                "re-read compares nothing and the gate is open for a tool that never wrote — "
                "name at least one {path: value}, or drop the person from the expectation"
            )
        for path, value in dict(fields).items():
            if value is None:
                raise ProbeError(
                    f"{name}: expect_person[{gramps_id!r}][{path!r}] is None, which a mistyped "
                    "path satisfies just as well as a real absence — use ABSENT to assert that "
                    "the leaf must not exist, or name the value it must hold"
                )


def _reject_uncovered_batch(
    name: str,
    self_report: SelfReport,
    arguments: Mapping[str, Any],
    expect_person: Mapping[str, Mapping[str, Any]] | None,
) -> None:
    """Every item the batch was handed has to be named (B4).

    A field write moves no counts, `count_guard_ok` is true by construction, and the identity
    difference sees nothing either — so an item the expectation does not name is unobservable by
    every other check in this suite. `_bulk_write` is best-effort by contract (`server.py:56-58`),
    which is exactly why the coverage has to come from the caller.
    """
    if self_report != "bulk":
        return
    if "items" not in arguments:
        raise ProbeError(
            f"{name}: self_report='bulk' but the call has no 'items' argument, so this rule has "
            "nothing to compare and would pass anything — teach it where this tool keeps its "
            "batch rather than letting the coverage check quietly become a no-op"
        )
    items = arguments.get("items") or []
    handed = {
        item["gramps_id"]
        for item in items
        if isinstance(item, Mapping) and item.get("gramps_id") is not None
    }
    uncovered = sorted(handed - set(expect_person or {}))
    if uncovered:
        raise ProbeError(
            f"{name}: the batch was handed {sorted(handed)} but expect_person covers only "
            f"{sorted(expect_person or {})} — {uncovered} would be written, dropped or mangled "
            "without any check noticing, because a field write moves no count"
        )
